from common import *
import importlib.util
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

BASE=HERE.parent/'2026-11-23-dwell-time'
def fmt(r):return f'{r.delta:+.5f} [{r.lower_95:+.5f}, {r.upper_95:+.5f}]'
def conclusion(r,metric='AP'):
    if metric=='Brier':return '改善 / improvement' if r.upper_95<0 else ('變差 / deterioration' if r.lower_95>0 else '區間跨零 / interval includes zero')
    return '改善 / improvement' if r.lower_95>0 else ('變差 / deterioration' if r.upper_95<0 else '區間跨零 / interval includes zero')
def main():
    spec=importlib.util.spec_from_file_location('prior_reporting',BASE/'report.py');rp=importlib.util.module_from_spec(spec);spec.loader.exec_module(rp)
    # Reuse diagnostics, with Electronics-specific semantic wording.
    original=rp.semantic
    def semantic(t):
        if t=='p2':return 'at least two distinct products observed so far'
        if t=='p3':return 'at least three distinct products observed so far'
        return original(t)
    rp.semantic=semantic
    fs=rp.formulas()
    if fs.empty:
        fs=pd.DataFrame(columns=["condition","contains_known_duration_bucket","contains_unknown_marker","temporal_syntax","exact_training_dwell_count_redundancy"]);fs.to_csv(HERE/"selected_formulas.csv",index=False)
    m=pd.read_csv(outdir('Electronics')/'metrics.csv');pairs=pd.read_csv(outdir('Electronics')/'paired_differences.csv')
    m.to_csv(HERE/'metrics.csv',index=False);pairs.to_csv(HERE/'paired_differences.csv',index=False)
    allm=pd.concat([pd.read_csv(BASE/'metrics.csv'),m],ignore_index=True);allp=pd.concat([pd.read_csv(BASE/'paired_differences.csv'),pairs],ignore_index=True)
    allm.to_csv(HERE/'three_dataset_metrics.csv',index=False);allp.to_csv(HERE/'three_dataset_paired_differences.csv',index=False)
    means=allm[allm.model=='NN'].groupby(['dataset','condition','metric']).value.agg(['mean','std']).reset_index();means.to_csv(HERE/'neural_mean_sd.csv',index=False)
    seedpairs=allp[allp.model=='NN'].groupby(['dataset','contrast','metric']).delta.agg(['mean','std']).reset_index();seedpairs.to_csv(HERE/'neural_paired_mean_sd.csv',index=False)
    lr=allm[allm.model=='LR'].pivot(index=['dataset','condition'],columns='metric',values='value').reset_index();lr.to_csv(HERE/'main_results.csv',index=False)
    (HERE/'results_table.tex').write_text(lr.to_latex(index=False,float_format='%.5f'),encoding='utf-8')
    nn=means.copy();nn['mean (sample SD)']=nn.apply(lambda r:f"{r['mean']:.5f} ({r['std']:.5f})",axis=1);nt=nn.pivot(index=['dataset','condition'],columns='metric',values='mean (sample SD)').reset_index();(HERE/'neural_results_table.tex').write_text(nt.to_latex(index=False),encoding='utf-8')
    nr=[]
    for c in CFG['neural_conditions']:
        for seed in CFG['neural_seeds']:
            d=outdir('Electronics')/f'{c}_{seed}';f=json.loads((d/'freeze.json').read_text());co=json.loads((d/'config.json').read_text());ep=json.loads((d/'epochs.json').read_text());nr.append(dict(dataset='Electronics',condition=c,seed=seed,parameters=f['parameters'],best_epoch=f['best_epoch'],epochs=f['epochs'],summary_dimension=co['summary_dim'],training_validation_seconds=sum(x['seconds'] for x in ep)))
    pd.DataFrame(nr).to_csv(HERE/'neural_runs.csv',index=False)
    costs=[]
    for c in ['M1','M3','M4','M5']:
        d=outdir('Electronics')/c;s=json.loads((d/'selection.json').read_text());steps=pd.read_csv(d/'selection_steps.csv') if (d/'selection_steps.csv').exists() else pd.DataFrame();costs.append(dict(dataset='Electronics',condition=c,initial=s['initial_candidate_count'],eligible=s['eligible_count'],selected=len(s['indices']),selection_seconds=steps.seconds.sum() if len(steps) else 0,candidate_refits=steps.candidate_count.sum() if len(steps) else 0))
    pd.DataFrame(costs).to_csv(HERE/'selection_cost.csv',index=False)
    pd.DataFrame(json.loads((outdir('Electronics')/'runtime.json').read_text())).to_csv(HERE/'runtime.csv',index=False)
    primary=allp[(allp.contrast=='M4-M3')&(allp.metric=='AP')&allp.model.isin(['LR','NN_mean'])].reset_index(drop=True)
    fig,ax=plt.subplots(figsize=(9,5.5))
    for i,r in primary.iterrows():ax.errorbar(r.delta,i,xerr=[[r.delta-r.lower_95],[r.upper_95-r.delta]],fmt='o',capsize=4,color='#126a89' if r.model=='LR' else '#b06420')
    ax.set_yticks(range(len(primary)),[f'{r.dataset} / {r.model}' for _,r in primary.iterrows()]);ax.axvline(0,color='gray',lw=1);ax.set_xlabel('Paired AP difference: M4 - M3 (95% percentile interval)');ax.set_title('Three datasets: fixed t=20, m=10, H=10; exploratory extension');ax.grid(axis='x',alpha=.2);fig.tight_layout();fig.savefig(HERE/'paired_ap_differences.png',dpi=200);fig.savefig(HERE/'paired_ap_differences.svg');plt.close(fig)
    prep=json.loads((outdir('Electronics')/'preparation.json').read_text())
    zh=['# 三資料集 dwell 補充比較','', 'Coveo、Cosmetics 沿用 2026-11-23 完成並凍結的結果；Electronics 是看過前兩組結果後，依使用者於 2026-11-26 要求新增的探索性擴充，不是原先事前固定範圍。沒有重跑或改選前兩資料集。新實驗仍只評估 t=20、m=10、H=10。','', '## 主要 AP 比較','',primary[['dataset','model','delta','lower_95','upper_95']].to_markdown(index=False),'', 'Electronics 的 t20 cohort 為 train558（95正例）、validation76（8正例）、test171（27正例，170 users）。樣本與驗證正例數很少，選模及效果估計可能不穩定；第三資料集不能自動當作更強或普遍的證據。','', '## Electronics 直接回答','']
    en=['# Three-dataset results and manuscript material','', 'The completed Coveo and Cosmetics experiments were retained unchanged. Electronics was added at the user’s request after those results were available; this is a sequential exploratory extension, not an originally prespecified third dataset. All new Electronics models, formulas and thresholds were frozen before its test evaluation. Each dataset uses event-20 observation, a recent ten-event raw window, and first purchase within the next ten recognized events.','']
    for model,contrasts in [('LR',['M2-M0','M4-M3','M4-M2','M4-M5']),('NN_mean',['M4-M3','M4-M2','M3-M2'])]:
        for ct in contrasts:
            rr=pairs[(pairs.model==model)&(pairs.contrast==ct)&(pairs.metric=='AP')].iloc[0]
            zh.append(f'- {model} {ct} AP：{fmt(rr)}；{conclusion(rr)}。')
            en.append(f'For Electronics, {model} {ct} yielded an AP difference of {fmt(rr)}.')
    zh+=['','M2−M0 回答普通時間特徵；M4−M3 回答擴充 learned vocabulary 流程；M4−M2 回答已有 T 後的額外邏輯收益；M4−M5 比較 learned LTLf 與 DECLARE。區間跨零不代表等價；不可將單一 operator 或事件間隔視為因果、注意力或普遍架構效益。','', '## 完整次要指標與 seed 變異','',pairs[pairs.model.isin(['LR','NN_mean'])].to_markdown(index=False),'',pairs[pairs.model=='NN'].to_markdown(index=False),'',seedpairs[seedpairs.dataset=='Electronics'].to_markdown(index=False)]
    en+=['','Electronics contains 558 training sessions (95 positives), 76 validation sessions (8 positives), and 171 test sessions (27 positives; 170 users). The small validation-positive count limits model-selection stability and the strength of generalization claims.','', 'Electronics secondary contrasts (higher MCC and lower Brier are preferable):','',pairs[(pairs.model.isin(['LR','NN_mean']))&(pairs.metric!='AP')][['model','contrast','metric','delta','lower_95','upper_95']].to_markdown(index=False),'','Per-seed Electronics differences:','',pairs[pairs.model=='NN'][['contrast','seed','metric','delta','lower_95','upper_95']].to_markdown(index=False)]
    sub=fs[fs.condition=='M4'];n=int(sub.contains_known_duration_bucket.sum());u=int(sub.contains_unknown_marker.sum());tmp=int(sub.temporal_syntax.sum());red=int(sub.exact_training_dwell_count_redundancy.fillna('').ne('').sum())
    zh+=['','## 公式診斷與資料限制','',f'M4 選中 {len(sub)} 個公式；{n} 個含已知間隔 bucket，{u} 個含 du，{tmp} 個含 temporal 語法；{red} 個與枚舉的單一 dwell-count 門檻規則在 training 完全相同。有限診斷不證明非冗餘，詳見 selected_formulas.csv。Electronics p2/p3 表示不同產品數，不是目前產品重複次數。',f'保留原 session split；t20 使用者跨 split 重疊數：{prep["user_overlap_between_splits"]}。按 user bootstrap 處理 test 內相關性，不能修補 train/test 使用者重疊。本輪不是 unseen-user 泛化測試。原始 已在訓練前排除同一 session key 對應多個 user 的歸屬不明 sessions；排除數列於 cohort_audit.csv。原始 source-edge 使用30分鐘 guard，短自然終止負例依給定 session ID 與已觀察歷史判定；不聲稱自然部署或所有 censoring 條件。','間隔先 slice 再計算，末端 unknown；零秒另行保留，buckets/scalers 僅 training 擬合。舊 Electronics master dwell 與 buckets 未使用。匹配 mining 使用 train t10/20/30 記錄但不新增這些 evaluation landmarks。舊 session-purchase 成績與本輪 future-horizon 結果不可直接配對。','', '## 改稿與時間成本','', '保留三資料集各自的 AP/MCC/Brier 與配對區間；將神經結論限於固定 encoder、融合方式和 LR 移用公式。縮小或刪除普遍提升、單一 dwell 因果作用、真實注意力、未顯著即等價與端到端加速等主張。歷史三資料集稽核見前輪 inventory；本輪三資料集新固定-landmark 結果另列，不能混為舊任務重現。','成本見 runtime.csv 與 selection_cost.csv：preprocessing、兩次匹配 vocabulary mining、selection、baseline classifier、neural training、inference 分列；selection 已含候選分類器重擬合不可重複加總。cached-input neural training 不等於整體速度。','', '## 三資料集表','',lr.to_markdown(index=False),'',nt.to_markdown(index=False),'','所有結果均 exploratory；interval 固定模型／公式／門檻，不含 mining 與 optimization-seed 不確定性。各 seed 共用 user/session resamples，不當成獨立三倍樣本；沒有多重比較校正。未自動展開下一輪。']
    en+=['',f'Of {len(sub)} selected Electronics M4 formulas, {n} referenced known-duration buckets and {u} referenced the unknown-gap marker; {tmp} contained temporal syntax. Electronics p2/p3 encode cumulative distinct-product counts. Count-threshold agreement is a limited training diagnostic, not proof of irreducible temporal information.',f'Sessions with multiple user IDs were excluded before any fit, with counts reported in cohort_audit.csv. Electronics otherwise retains the audited historical session split; eligible-cohort user overlaps are {prep["user_overlap_between_splits"]}. User-cluster bootstrap does not remove cross-split user overlap. These results therefore do not measure unseen-user generalization. Outgoing gaps are formed after truncation, the terminal gap is unknown, genuine zero gaps remain distinguishable, and timing transformations use training data only.','All comparisons are exploratory. Intervals condition on fitted models, selected formulas and validation thresholds; they omit mining and optimization-seed uncertainty and are not multiplicity-adjusted. Formulas selected by LR are transferred unchanged to neural models. No pooled cross-dataset significance claim is made. Historical session-purchase results are background, not paired controls for the new landmark task.','',lr.to_markdown(index=False),'',nt.to_markdown(index=False),'','Figure caption. Paired M4−M3 AP differences on three datasets at t=20, m=10 and H=10. Bars are 95% percentile intervals from 1,500 shared cluster bootstrap resamples, by user for Electronics and Cosmetics and by session for Coveo. Neural points average paired differences across seeds42–44 using identical cluster resamples, keeping each model fixed. Electronics is a subsequent exploratory extension; Coveo and Cosmetics retain the previously completed results.']
    zh[2:2]=['## 結果綜合判讀','', '新增 Electronics 後，三資料集的 LR 與三 seed 平均神經模型共六項主要 M4−M3 AP 比較，其 95% 配對區間皆跨零。這些實驗未提供 dwell vocabulary 穩定增加 AP 的證據，也不構成等價證明。Electronics 的 LR AP 差為 −0.03988 [−0.12317, +0.02018]；神經平均為 −0.00125 [−0.00585, +0.00359]。','Electronics 的次要結果也不支持普遍提升：LR M2−M0 的 MCC 下降 −0.16438 [−0.30918, −0.00570]；LR M4−M2 的 Brier 上升 +0.01445 [+0.00231, +0.02828]。神經 M4−M3 的平均 MCC 下降 −0.11741 [−0.17797, −0.04581]，其中 seed42 的差異為 −0.32967、seed43 為 −0.02255、seed44 為 0，效果集中於一個 seed。','神經 M4−M2 的平均 Brier 改善 −0.01602 [−0.02227, −0.01030]，但三 seed 差異為 +0.01486、−0.01806、−0.04487，方向不一致；M3−M2 的平均改善甚至略大（−0.01660）。故這項改善不能專屬歸因於 dwell vocabulary。MCC 使用各模型在僅 8 個正例的 validation set 選出的門檻，應連同 AP、Brier 與 seed 表解讀。','M4 的 10 個公式中 7 個含已知間隔 bucket、0 個含 du、9 個含 temporal operator；單獨原子 dl 也是選中公式，因此不應聲稱全部都是時間運算子規則。沒有與本輪枚舉的單一 dwell-count 門檻完全相同者，但此診斷不排除其他冗餘。','兩次候選池挖掘各約 436 與 513 秒；四組選擇合計約 305 秒，含 6,260 次候選 refits。成本是本機測量，不能由 cached-input 神經訓練時間推論端到端加速。','']
    en[2:2]=['Across all three datasets, the six primary M4–M3 AP intervals (LR and three-seed neural means) included zero. The extension therefore provides no consistent evidence that adding the dwell vocabulary improves AP; it does not establish equivalence. Electronics yielded −0.03988 [−0.12317, +0.02018] for LR and −0.00125 [−0.00585, +0.00359] for the neural mean.','Secondary outcomes were mixed or adverse. For Electronics, LR M2–M0 reduced MCC by 0.16438 (interval −0.30918 to −0.00570), while LR M4–M2 increased Brier by 0.01445 (0.00231 to 0.02828). Neural M4–M3 reduced mean MCC by 0.11741 (−0.17797 to −0.04581), concentrated in seed42: the three paired differences were −0.32967, −0.02255, and 0. Validation-selected thresholds are especially uncertain with only eight validation positives.','Neural M4–M2 improved mean Brier by 0.01602 (−0.02227 to −0.01030), but its seed differences were +0.01486, −0.01806, and −0.04487. M3–M2 had a slightly larger mean improvement (−0.01660), so this benefit cannot be attributed specifically to the dwell vocabulary. These conditional, unadjusted intervals should be interpreted alongside seed variation and the primary AP outcome.','Seven of the ten Electronics M4 formulas contained known-gap buckets, none contained the unknown marker, and nine contained temporal operators; the remaining formula was the atomic proposition dl. No formula exactly matched the enumerated univariate dwell-count thresholds on training rows, which does not rule out other forms of redundancy. Candidate mining took approximately 436 and 513 seconds; the four selection procedures required approximately 305 seconds and 6,260 candidate refits. These local timings do not establish end-to-end acceleration.','']
    (HERE/'report_zh.md').write_text('\n'.join(zh).replace('原始 已在訓練前','已在訓練前'),encoding='utf-8');(HERE/'manuscript_results_en.md').write_text('\n'.join(en),encoding='utf-8')
    save(HERE/'aggregate_provenance.json',dict(previous_artifacts={n:sha(BASE/n) for n in ['metrics.csv','paired_differences.csv','completion.json','final_validation.json']},new_dataset='Electronics',extension_after_previous_results=True))
    save(HERE/'completion.json',dict(complete=False,reports_generated=True,new_LR_conditions=6,new_neural_fits=9,combined_LR_conditions=18,combined_neural_fits=27))
if __name__=='__main__':main()
